        {'atomic_rule_id': 'GB51210-2016-8.3.8@bracing_layout', 'clause_text': '支撑脚手架剪刀撑或斜撑杆、交叉拉杆的布置应均匀、 对称。', 'rule_family': 'visual_structural', 'judge_dimension': '判断支撑脚手架可见立面/平面内剪刀撑、斜撑杆或交叉拉杆的布置间距与方向是否均匀、对称，不判断杆件连接强度、材质或隐蔽部位。', 'judge_boundary': {'compliant': '在可见的支撑脚手架范围内，剪刀撑或斜撑杆、交叉拉杆的布置间距、方向、数量呈现均匀、对称，未见明显偏置、缺失或方向不一致。', 'non_compliant': '在可见的支撑脚手架范围内，剪刀撑或斜撑杆、交叉拉杆的布置存在明显不均匀（如一侧密集一侧稀疏、间距突变）或明显不对称（如仅单侧设置、方向相反、交叉拉杆偏置），且该状态已被照片直接呈现。', 'doubtful': '同一可见支撑脚手架范围内，因拍摄角度、遮挡或局部可见范围导致无法判断整体均匀对称性，且可见部分存在互相矛盾的布置特征时，仅记录为存疑。'}, 'applicability': {'all_of': ['场景为支撑脚手架（SCAFFOLD_COUPLER_TYPE、SCAFFOLD_DISC_BUCKLE等）', '照片中可见剪刀撑、斜撑杆或交叉拉杆的布置区域'], 'not_applicable_when': ['照片中不可见剪刀撑、斜撑杆或交叉拉杆', '仅可见作业脚手架连墙件或非支撑脚手架杆件', '杆件被完全遮挡无法判断布置关系']}, 'evidence_requirements': ['能显示支撑脚手架立面或平面内剪刀撑/斜撑杆/交叉拉杆布置的整体或局部照片', '可见杆件的间距、方向、数量及相对位置关系'], 'disambiguation_notes': ['不要将作业脚手架的连墙件布置混入本规则判断', '不要因局部遮挡直接判为违规，遮挡区域不构成违规证据', '均匀对称性需基于可见范围的整体关系判断，单根杆件缺失需结合上下文确认是否为设计布置'], 'keywords': ['支撑脚手架', '剪刀撑', '斜撑杆', '交叉拉杆', '均匀', '对称', '布置'], 'similar_words': ['剪刀撑布置', '斜撑布置', '交叉拉杆设置', '支撑架斜撑'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '支撑脚手架剪刀撑/斜撑杆/交叉拉杆布置区域', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-3-8', 'standard_code': 'GB 51210-2016', 'article': '第8.3.8条', 'align_score': 0.87, 'subject': '架体外立面的杆件网格', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'BRACING_LAYOUT'},
