        {'atomic_rule_id': 'GB51210-2016-6@structure_damage', 'clause_text': '倒手架所依附、承受的工程结构不应受到损害。', 'rule_family': 'visual_structural', 'judge_dimension': '判断脚手架附着/支承处的工程结构本体是否出现可见损伤，不判断脚手架杆件、连墙件自身是否合规。', 'judge_boundary': {'compliant': '附着或支承部位的工程结构表面未见裂缝、压碎、剥落、明显变形、穿孔等可见损伤痕迹。', 'non_compliant': '可见证据直接显示脚手架附着或支承处的工程结构出现裂缝、混凝土压碎剥落、钢筋外露、结构构件明显变形或穿孔等损伤。', 'doubtful': '附着/支承部位被脚手架杆件、连墙件、装饰层或遮挡物完全遮蔽，无法看清结构本体状态时，不判违规也不判合规，仅记录为存疑。'}, 'applicability': {'all_of': ['脚手架通过连墙件、附着支承或底部支承与工程结构相连', '照片中能看到附着点或支承点周边的结构本体'], 'not_applicable_when': ['脚手架为独立落地且照片未拍到与主体结构连接部位', '附着点完全被遮挡且无任何结构本体可见']}, 'evidence_requirements': ['能看清连墙件/附着支承/底部支承与工程结构接触部位的照片', '结构本体表面状态可见（裂缝、剥落、变形等）'], 'disambiguation_notes': ['区分脚手架杆件自身变形与工程结构本体损伤，只判后者', '装饰层开裂不等同于结构本体损伤，需能判断为结构构件', '阴影、污渍、模板拼缝不应误判为裂缝'], 'keywords': ['脚手架附着', '连墙件', '结构损伤', '裂缝', '剥落', '支承部位'], 'similar_words': ['依附结构受损', '支承结构损坏', '附着处结构破坏'], 'scene_hint': 'SCAFFOLD_ATTACHED_LIFTING', 'subject_hint': '脚手架附着/支承处的工程结构本体', 'subject_cue': '连墙件或支承座与墙、梁、板接触部位的结构表面', 'note': '', 'regulation_id': 'STD-GB-51210-2016-6', 'standard_code': 'GB 51210-2016', 'article': '第6条', 'align_score': 0.278, 'subject': '脚手架附着/支承处的工程结构本体', 'subject_score': 0.286, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'STRUCTURE_DAMAGE'},
