        {'atomic_rule_id': 'GB51210-2016-4@structure_deformation', 'clause_text': '在使用中，脚手架结构性能不得发生明显改变；', 'rule_family': 'visual_structural', 'judge_dimension': '判断在用脚手架可见结构构件是否出现明显变形、弯曲、扭曲、下沉或杆件缺失等使结构性能明显改变的外观迹象；不判断材料强度、承载力验算及隐蔽节点内部状态。', 'judge_boundary': {'compliant': '在可见的立杆、横杆、剪刀撑、连墙件及节点区域，未见明显弯曲、扭曲、局部压屈、异常下沉或杆件缺失等结构性能改变迹象。', 'non_compliant': '可见证据直接显示立杆或横杆出现明显弯曲、扭曲、局部压屈变形，或剪刀撑、连墙件等主要杆件明显缺失、松脱，导致结构外观形态明显偏离正常受力状态。', 'doubtful': '同一可见杆件或节点区域存在互相矛盾的可见特征（如疑似变形但被连接件遮挡、角度异常但无法确认是安装偏差还是受力变形），无法据可见证据判定是否属于明显结构性能改变。'}, 'applicability': {'all_of': ['脚手架处于使用状态且主要结构杆件在画面中可见'], 'not_applicable_when': ['画面仅显示局部脚手板或防护栏杆，主要结构杆件不可见', '脚手架尚未搭设或已拆除']}, 'evidence_requirements': ['能看清立杆、横杆、剪刀撑或连墙件整体线形的照片', '能判断杆件是否缺失、松脱的节点区域可见证据'], 'disambiguation_notes': ['安装偏差造成的轻微不垂直不等同于使用中结构性能明显改变', '杆件表面锈蚀、污渍本身不构成本条违规', '被遮挡部位不得直接判为违规或存疑'], 'keywords': ['脚手架', '结构性能', '明显改变', '变形', '弯曲', '扭曲', '杆件缺失'], 'similar_words': ['结构变形', '杆件变形', '脚手架失稳迹象'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '在用脚手架主要结构杆件及节点', 'subject_cue': '立杆横杆剪刀撑的线形与连接节点', 'note': '', 'regulation_id': 'STD-GB-51210-2016-4', 'standard_code': 'GB 51210-2016', 'article': '第4条', 'align_score': 0.444, 'subject': '在用脚手架主要结构杆件及节点', 'subject_score': 0.231, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'STRUCTURE_DEFORMATION'},
