        {'atomic_rule_id': 'GB51210-2016-4.0.12@anti-disengagement', 'clause_text': '脚手架挂扣式连接、承插式连接的连接件应有防止退出 或防止脱落的措施。', 'rule_family': 'visual_structural', 'judge_dimension': '判断挂扣式或承插式连接件上是否可见防退出/防脱落措施（如插销、锁片、卡簧、限位凸起等），不判断连接件的承载力或内部锁止状态。', 'judge_boundary': {'compliant': '在可见的挂扣式或承插式连接节点上，连接件已呈现插销插入、锁片闭合、卡簧到位等防退出/防脱落措施，且未见该措施缺失或未就位的可见迹象。', 'non_compliant': '在可见的挂扣式或承插式连接节点上，连接件明显缺少防退出/防脱落措施（如插销未插入、锁片未闭合、卡簧缺失），或防脱落措施明显未处于工作位置。', 'doubtful': '同一可见连接节点上，防退出/防脱落措施的存在状态互相矛盾（如一侧有插销、另一侧同类型节点无插销且无遮挡），无法判定该节点是否具备防脱落措施。'}, 'applicability': {'all_of': ['画面中可辨认出挂扣式连接或承插式连接的连接件节点', '连接件节点处于可见、可复核状态'], 'not_applicable_when': ['画面中无挂扣式或承插式连接件节点', '连接件节点被完全遮挡或模糊无法辨认']}, 'evidence_requirements': ['能清晰显示挂扣式或承插式连接件节点的照片', '能辨认防退出/防脱落措施（插销、锁片、卡簧、限位件等）是否存在的可见细节'], 'disambiguation_notes': ['不要将扣件式钢管脚手架的旋转扣件、直角扣件误判为挂扣式或承插式连接件', '防脱落措施缺失需直接可见，不得仅因照片角度看不到插销就判违规', '连接件被安全网、密目网或材料完全遮挡时，不适用本规则裁决'], 'keywords': ['挂扣式连接', '承插式连接', '连接件', '防退出', '防脱落', '插销', '锁片', '卡簧'], 'similar_words': ['盘扣节点插销', '承插接头防脱', '挂扣锁止'], 'scene_hint': 'SCAFFOLD_DISC_BUCKLE', 'subject_hint': '挂扣式或承插式连接件节点', 'subject_cue': '圆盘节点插销、承插接头锁片或卡簧', 'note': '', 'regulation_id': 'STD-GB-51210-2016-4-0-12', 'standard_code': 'GB 51210-2016', 'article': '第4.0.12条', 'align_score': 0.423, 'subject': '挂扣式或承插式连接件节点', 'subject_score': 0.182, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'ANTI-DISENGAGEMENT'},
        {'atomic_rule_id': 'GB51210-2016-4.0.12@anti-disengagement', 'clause_text': '脚手架挂扣式连接、承插式连接的连接件应有防止退出 或防止脱落的措施。', 'rule_family': 'visual_structural', 'judge_dimension': '判断挂扣式或承插式连接件上是否可见防退出/防脱落措施（如插销、锁片、卡簧、限位凸起等），不判断连接件的承载力或内部锁止状态。', 'judge_boundary': {'compliant': '在可见的挂扣式或承插式连接节点上，连接件已呈现插销插入、锁片闭合、卡簧到位等防退出/防脱落措施，且未见该措施缺失或未就位的可见迹象。', 'non_compliant': '在可见的挂扣式或承插式连接节点上，连接件明显缺少防退出/防脱落措施（如插销未插入、锁片未闭合、卡簧缺失），或防脱落措施明显未处于工作位置。', 'doubtful': '同一可见连接节点上，防退出/防脱落措施的存在状态互相矛盾（如一侧有插销、另一侧同类型节点无插销且无遮挡），无法判定该节点是否具备防脱落措施。'}, 'applicability': {'all_of': ['画面中可辨认出挂扣式连接或承插式连接的连接件节点', '连接件节点处于可见、可复核状态'], 'not_applicable_when': ['画面中无挂扣式或承插式连接件节点', '连接件节点被完全遮挡或模糊无法辨认']}, 'evidence_requirements': ['能清晰显示挂扣式或承插式连接件节点的照片', '能辨认防退出/防脱落措施（插销、锁片、卡簧、限位件等）是否存在的可见细节'], 'disambiguation_notes': ['不要将扣件式钢管脚手架的旋转扣件、直角扣件误判为挂扣式或承插式连接件', '防脱落措施缺失需直接可见，不得仅因照片角度看不到插销就判违规', '连接件被安全网、密目网或材料完全遮挡时，不适用本规则裁决'], 'keywords': ['挂扣式连接', '承插式连接', '连接件', '防退出', '防脱落', '插销', '锁片', '卡簧'], 'similar_words': ['盘扣节点插销', '承插接头防脱', '挂扣锁止'], 'scene_hint': 'SCAFFOLD_DISC_BUCKLE', 'subject_hint': '挂扣式或承插式连接件节点', 'subject_cue': '圆盘节点插销、承插接头锁片或卡簧', 'note': '', 'regulation_id': 'STD-GB-51210-2016-4-0-12', 'standard_code': 'GB 51210-2016', 'article': '第4.0.12条', 'align_score': 0.423, 'subject': '挂扣式或承插式连接件节点', 'subject_score': 0.182, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'ANTI-DISENGAGEMENT'},
