        {'atomic_rule_id': 'GB51210-2016-11.2.4@outer_mesh_enclosure', 'clause_text': '作业脚手架外侧和支撑脚手架作业层栏杆应采用密 目式安全网或其他措施全封闭防护。密目式安全网应为阻燃 产品O', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业脚手架外侧是否被密目式安全网或其他封闭防护措施连续覆盖，不判断安全网的阻燃性能。', 'judge_boundary': {'compliant': '在可见的作业脚手架外侧范围内，未见防护网缺失、脱落或明显未封闭的可见证据。', 'non_compliant': '可见作业脚手架外侧存在未设置密目式安全网或其他封闭防护措施的区域，或防护网明显缺失、脱落、未连续封闭。', 'doubtful': '同一可见外侧区域，防护网存在但无法判断是否连续封闭，且无其他直接冲突证据时不判 doubtful。'}, 'applicability': {'all_of': ['画面中可见作业脚手架外侧立面'], 'not_applicable_when': ['画面中无作业脚手架外侧立面', '外侧立面完全被遮挡无法观察']}, 'evidence_requirements': ['能显示作业脚手架外侧立面防护网覆盖状态的可见照片或视频帧'], 'disambiguation_notes': ['密目式安全网与普通安全网、防尘网外观相近，需结合网孔密度和安装位置判断', '局部破损但整体封闭不直接判 non_compliant，需达到明显未封闭程度'], 'keywords': ['作业脚手架', '外侧', '密目式安全网', '全封闭防护'], 'similar_words': ['外立面防护', '密目网封闭', '脚手架外侧封闭'], 'scene_hint': 'SCAFFOLD_ATTACHED_LIFTING', 'subject_hint': '作业脚手架外侧立面防护网', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-4', 'standard_code': 'GB 51210-2016', 'article': '第11.2.4条', 'align_score': 0.439, 'subject': '架体外侧封闭区域', 'subject_score': 0.636, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'OUTER_MESH_ENCLOSURE'},
        {'atomic_rule_id': 'GB51210-2016-11.2.4@platform_guardrail_enclosure', 'clause_text': '作业脚手架外侧和支撑脚手架作业层栏杆应采用密 目式安全网或其他措施全封闭防护。密目式安全网应为阻燃 产品O', 'rule_family': 'visual_direct', 'judge_dimension': '判断支撑脚手架作业层栏杆是否被密目式安全网或其他措施全封闭防护，不判断栏杆结构强度。', 'judge_boundary': {'compliant': '在可见的支撑脚手架作业层栏杆范围内，未见防护网缺失、脱落或明显未封闭的可见证据。', 'non_compliant': '可见支撑脚手架作业层栏杆存在未设置密目式安全网或其他封闭防护措施的区域，或防护网明显缺失、脱落、未连续封闭。', 'doubtful': '同一可见栏杆区域，防护网存在但无法判断是否连续封闭，且无其他直接冲突证据时不判 doubtful。'}, 'applicability': {'all_of': ['画面中可见支撑脚手架作业层栏杆'], 'not_applicable_when': ['画面中无支撑脚手架作业层栏杆', '栏杆区域完全被遮挡无法观察']}, 'evidence_requirements': ['能显示支撑脚手架作业层栏杆防护网覆盖状态的可见照片或视频帧'], 'disambiguation_notes': ['需区分作业层栏杆与外侧立面防护，本规则针对作业层栏杆范围', '局部破损但整体封闭不直接判 non_compliant，需达到明显未封闭程度'], 'keywords': ['支撑脚手架', '作业层栏杆', '密目式安全网', '全封闭防护'], 'similar_words': ['作业层防护', '栏杆封闭', '密目网围挡'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '支撑脚手架作业层栏杆防护网', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-4', 'standard_code': 'GB 51210-2016', 'article': '第11.2.4条', 'align_score': 0.585, 'subject': '架体外侧封闭区域', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'PLATFORM_GUARDRAIL_ENCLOSURE'},
