        {'atomic_rule_id': 'GB51210-2016-11.2.5@corner_hard_protection', 'clause_text': '作业脚手架临街的外侧立面、转角处应采取硬防护措 施，硬防护的高度不应小于1.2m,转角处硬防护的宽度应为作 业脚手架宽度。', 'rule_family': 'visual_direct', 'judge_dimension': '判断临街作业脚手架转角处是否设置硬防护及其宽度是否覆盖脚手架宽度，不判断转角处防护高度及非临街转角。', 'judge_boundary': {'compliant': '临街转角处可见硬防护，且其宽度覆盖脚手架转角处全宽（与脚手架宽度一致）。', 'non_compliant': '临街转角处可见未设置硬防护，或硬防护宽度明显小于脚手架宽度（如仅覆盖转角一侧、宽度不足）。', 'doubtful': '转角处硬防护宽度与脚手架宽度在可见范围内直接矛盾，无法判定是否覆盖全宽。'}, 'applicability': {'all_of': ['作业脚手架存在临街转角', '照片可辨识转角处防护设置及脚手架宽度'], 'not_applicable_when': ['脚手架无临街转角', '照片无法辨识转角处防护或脚手架宽度']}, 'evidence_requirements': ['能显示转角处硬防护设置的照片', '能显示脚手架转角宽度的可见参照'], 'disambiguation_notes': ['转角处硬防护宽度应等于脚手架宽度，不是仅指防护板自身宽度', '密目网不属于硬防护', '非临街转角不适用本条'], 'keywords': ['转角处', '硬防护', '宽度', '脚手架宽度', '临街'], 'similar_words': ['转角硬防护', '转角防护宽度'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '临街作业脚手架转角处硬防护', 'subject_cue': '脚手架转角位置设置的硬质防护板，宽度覆盖转角', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-5', 'standard_code': 'GB 51210-2016', 'article': '第11.2.5条', 'align_score': 0.325, 'subject': '临街作业脚手架转角处硬防护', 'subject_score': 0.333, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'CORNER_HARD_PROTECTION'},
