        {'atomic_rule_id': 'GB51210-2016-11.2.6@loaded_work_layers', 'clause_text': '作业脚手架同时满载作业的层数不应超过2层。', 'rule_family': 'visual_structural', 'judge_dimension': '判断作业脚手架上同时存在满载作业（人员集中作业、堆放材料或设备）的层数是否超过2层；不判断单层作业人数、材料重量是否满足荷载设计值。', 'judge_boundary': {'compliant': '在可见的作业脚手架范围内，同时处于满载作业状态的层数不超过2层，且未见第3层及以上存在人员集中作业或材料设备堆载的可见证据。', 'non_compliant': '在可见的作业脚手架范围内，可明确识别出3个及以上层同时存在人员集中作业或材料、设备堆载等满载作业状态。', 'doubtful': '同一可见作业层上，人员作业与材料堆载的层数归属存在直接冲突（如某层是否属于满载作业层无法从可见特征判定），且该冲突直接影响是否超过2层的结论。'}, 'applicability': {'all_of': ['作业脚手架已搭设并处于使用阶段', '照片能分辨脚手架各作业层及层上人员或堆载情况'], 'not_applicable_when': ['脚手架处于搭设或拆除阶段', '照片仅拍到局部单层，无法分辨层数与层上作业状态']}, 'evidence_requirements': ['能覆盖脚手架多个作业层的可见照片', '各层上人员集中作业或材料设备堆载的可见特征', '可区分层数的立杆、横杆或作业层踏板等参照物'], 'disambiguation_notes': ['仅凭单层局部照片不能推断其他层状态，不得据此判 non_compliant', '人员正常通行、少量工具放置不等同于满载作业', '被遮挡层不得直接计入或排除，只有可见证据直接支撑时才判违规'], 'keywords': ['作业脚手架', '满载作业层数', '同时作业层数', '2层', '堆载'], 'similar_words': ['同时施工层数', '同时作业层', '满载层数'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架各作业层及层上人员、材料设备', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-6', 'standard_code': 'GB 51210-2016', 'article': '第11.2.6条', 'align_score': 0.667, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.375, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'LOADED_WORK_LAYERS'},
        {'atomic_rule_id': 'GB51210-2016-11.2.7@fire_prevention', 'clause_text': '在脚手架作业层上进行电焊、气焊和其他动火作业时, 应采取防火措施，并应设专人监护。', 'rule_family': 'visual_direct', 'judge_dimension': '判断脚手架作业层动火作业点是否配置可见的防火措施（接火斗、防火毯、灭火器等），不判断动火审批手续和人员资质。', 'judge_boundary': {'compliant': '作业层动火作业点可见接火斗、防火毯、灭火器等防火措施，且未见违规事实。', 'non_compliant': '作业层上可见正在进行的电焊、气焊或其他动火作业，且作业点及下方未见任何接火斗、防火毯、灭火器等防火措施。', 'doubtful': '动火作业点可见防火措施，但被遮挡或状态无法确认是否有效覆盖火花飞溅区域。'}, 'applicability': {'all_of': ['脚手架作业层上正在进行或刚完成电焊、气焊或其他动火作业'], 'not_applicable_when': ['作业层上未见动火作业迹象', '动火作业不在脚手架作业层上进行']}, 'evidence_requirements': ['可见的动火作业迹象（焊渣、火花、焊机、气瓶等）', '作业点及下方防火措施配置情况'], 'disambiguation_notes': ['防火措施不限于灭火器，接火斗、防火毯、防火隔板均算', '仅看到焊机但未见动火作业，不判违规', '防火措施被遮挡无法确认时，不直接判 non_compliant'], 'keywords': ['脚手架', '作业层', '动火作业', '电焊', '气焊', '防火措施', '接火斗', '灭火器'], 'similar_words': ['焊接作业防火', '动火防火措施', '脚手架动火'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架作业层动火作业点及下方区域', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-7', 'standard_code': 'GB 51210-2016', 'article': '第11.2.7条', 'align_score': 0.5, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.357, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'FIRE_PREVENTION'},
        {'atomic_rule_id': 'GB51210-2016-11.2.7@fire_watch', 'clause_text': '在脚手架作业层上进行电焊、气焊和其他动火作业时, 应采取防火措施，并应设专人监护。', 'rule_family': 'visual_direct', 'judge_dimension': '判断脚手架作业层动火作业时，作业点附近是否可见专职监护人员，不判断监护人员资质和培训记录。', 'judge_boundary': {'compliant': '动火作业点附近可见专职监护人员，且未见违规事实。', 'non_compliant': '作业层上可见正在进行的电焊、气焊或其他动火作业，且作业点附近未见任何监护人员。', 'doubtful': '动火作业点附近有人，但无法判断是否为专职监护人员。'}, 'applicability': {'all_of': ['脚手架作业层上正在进行或刚完成电焊、气焊或其他动火作业'], 'not_applicable_when': ['作业层上未见动火作业迹象', '动火作业不在脚手架作业层上进行']}, 'evidence_requirements': ['可见的动火作业迹象', '作业点附近人员位置和状态'], 'disambiguation_notes': ['监护人员应位于动火点附近且注意力在动火作业上', '仅看到有人经过或作业人员本人，不视为监护人员', '监护人员被遮挡无法确认时，不直接判 non_compliant'], 'keywords': ['脚手架', '作业层', '动火作业', '专人监护', '监护人员'], 'similar_words': ['动火监护', '看火人', '防火监护人'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架作业层动火作业点附近人员', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-7', 'standard_code': 'GB 51210-2016', 'article': '第11.2.7条', 'align_score': 0.471, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.385, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'FIRE_WATCH'},
        {'atomic_rule_id': 'GB51210-2016-8.2.1@width', 'clause_text': '作业脚手架的宽度不应小于0. 8m,且不宜大于1.2m。 作业层高度不应小于1. 7m,且不宜大于2. Omo', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业脚手架架体宽度（内外立杆之间的净距或作业面宽度）是否满足下限0.8m及上限1.2m的构造要求，不判断连墙件、高度等其他构造。', 'judge_boundary': {'compliant': '在可清晰辨认架体宽度的照片中，实测或目测估算宽度处于0.8m~1.2m之间，且无可见证据表明宽度小于0.8m或大于1.2m。', 'non_compliant': '有可见证据（如卷尺实测、与已知尺寸构件对比）直接显示架体宽度小于0.8m或大于1.2m。', 'doubtful': '同一架体宽度在照片中因透视、遮挡等原因出现互相矛盾的可见特征，无法确定是否在0.8m~1.2m范围内。'}, 'applicability': {'all_of': ['作业脚手架架体已搭设，且照片中可辨认内外立杆或作业面宽度'], 'not_applicable_when': ['非作业脚手架（如支撑脚手架）', '架体宽度被完全遮挡无法辨认', '照片中无任何可参照尺寸的构件']}, 'evidence_requirements': ['能显示架体宽度全貌或局部带参照物的照片', '卷尺实测读数（如有）', '与已知尺寸构件（如钢管直径48mm）的对比'], 'disambiguation_notes': ['宽度指内外立杆之间的净距，不是作业面铺设宽度', '透视变形可能导致目测偏差，需结合参照物', '不宜大于1.2m为推荐性上限，超限时需有设计依据才可判违规'], 'keywords': ['作业脚手架', '架体宽度', '0.8m', '1.2m', '内外立杆间距'], 'similar_words': ['脚手架宽度', '作业面宽度', '架体横向宽度'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架架体宽度', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-2-1', 'standard_code': 'GB 51210-2016', 'article': '第8.2.1条', 'align_score': 0.379, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'WIDTH'},
        {'atomic_rule_id': 'GB51210-2016-8.2.1@height', 'clause_text': '作业脚手架的宽度不应小于0. 8m,且不宜大于1.2m。 作业层高度不应小于1. 7m,且不宜大于2. Omo', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业层高度（作业面至上方横杆或防护栏杆的垂直净高）是否满足下限1.7m及上限2.0m的构造要求，不判断宽度、连墙件等其他构造。', 'judge_boundary': {'compliant': '在可清晰辨认作业层高度的照片中，实测或目测估算高度处于1.7m~2.0m之间，且无可见证据表明高度小于1.7m或大于2.0m。', 'non_compliant': '有可见证据（如卷尺实测、与已知尺寸构件对比）直接显示作业层高度小于1.7m或大于2.0m。', 'doubtful': '同一作业层高度在照片中因透视、遮挡等原因出现互相矛盾的可见特征，无法确定是否在1.7m~2.0m范围内。'}, 'applicability': {'all_of': ['作业脚手架作业层已搭设，且照片中可辨认作业面至上方横杆或防护栏杆的垂直距离'], 'not_applicable_when': ['非作业脚手架', '作业层高度被完全遮挡无法辨认', '照片中无任何可参照尺寸的构件']}, 'evidence_requirements': ['能显示作业层高度全貌或局部带参照物的照片', '卷尺实测读数（如有）', '与已知尺寸构件（如钢管直径48mm）的对比'], 'disambiguation_notes': ['作业层高度指作业面至上方横杆或防护栏杆的垂直净高，不是层高', '不宜大于2.0m为推荐性上限，超限时需有设计依据才可判违规', '需区分作业层高度与步距'], 'keywords': ['作业层高度', '1.7m', '2.0m', '防护栏杆高度', '作业面净高'], 'similar_words': ['作业层净高', '作业面高度', '防护高度'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架作业层高度', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-2-1', 'standard_code': 'GB 51210-2016', 'article': '第8.2.1条', 'align_score': 0.31, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'HEIGHT'},
        {'atomic_rule_id': 'GB51210-2016-11.2.1@overload', 'clause_text': '脚手架作业层上的荷载不得超过设计允许荷载。', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业层上可见的堆载物与作业人员是否明显超出该脚手架设计允许荷载；不判断设计荷载数值本身，也不判断被遮挡或不可见区域的荷载。', 'judge_boundary': {'compliant': '作业层上可见的堆载物种类、数量与人员分布未呈现明显超载迹象，且现场可见荷载标识或设计允许荷载说明与可见堆载不矛盾。', 'non_compliant': '作业层上可见堆载物明显超出该脚手架设计允许荷载（如集中堆放大量砖块、砂浆桶、模板、钢筋等重型材料，或堆载高度、密度明显异常），且现场可见荷载标识或设计允许荷载说明显示已超限。', 'doubtful': '同一作业层上可见的堆载物与现场可见荷载标识或设计允许荷载说明存在直接冲突，但无法确认哪一方准确。'}, 'applicability': {'all_of': ['脚手架作业层已搭设完成并处于使用状态', '照片中可见作业层上的堆载物或人员分布', '现场可见荷载标识或设计允许荷载说明，或堆载物种类数量可辨识'], 'not_applicable_when': ['作业层上无可见堆载物且无人员作业', '照片无法辨识作业层上的堆载物种类或数量', '现场无荷载标识且堆载物种类数量无法判断']}, 'evidence_requirements': ['作业层上堆载物的可见照片', '现场荷载标识或设计允许荷载说明的可见照片', '作业人员分布与数量的可见证据'], 'disambiguation_notes': ['不要把正常施工材料临时堆放直接判为超载，需结合荷载标识或明显异常堆载判断', '不要因看不见作业层局部而判 doubtful，遮挡不等于冲突', '设计允许荷载数值本身不可见时，不应仅凭堆载外观判 non_compliant，除非堆载明显异常'], 'keywords': ['作业层荷载', '设计允许荷载', '堆载', '超载', '脚手架作业层'], 'similar_words': ['施工荷载', '作业层堆载', '脚手架荷载限值'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架作业层上的堆载物及作业人员', 'subject_cue': '', 'note': '设计允许荷载数值需结合现场标识或方案资料，静态照片仅能判断明显超载迹象。', 'regulation_id': 'STD-GB-51210-2016-11-2-1', 'standard_code': 'GB 51210-2016', 'article': '第11.2.1条', 'align_score': 0.556, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.357, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'OVERLOAD'},
        {'atomic_rule_id': 'GB51210-2016-11.2.6@loaded_work_layers', 'clause_text': '作业脚手架同时满载作业的层数不应超过2层。', 'rule_family': 'visual_structural', 'judge_dimension': '判断作业脚手架上同时存在满载作业（人员集中作业、堆放材料或设备）的层数是否超过2层；不判断单层作业人数、材料重量是否满足荷载设计值。', 'judge_boundary': {'compliant': '在可见的作业脚手架范围内，同时处于满载作业状态的层数不超过2层，且未见第3层及以上存在人员集中作业或材料设备堆载的可见证据。', 'non_compliant': '在可见的作业脚手架范围内，可明确识别出3个及以上层同时存在人员集中作业或材料、设备堆载等满载作业状态。', 'doubtful': '同一可见作业层上，人员作业与材料堆载的层数归属存在直接冲突（如某层是否属于满载作业层无法从可见特征判定），且该冲突直接影响是否超过2层的结论。'}, 'applicability': {'all_of': ['作业脚手架已搭设并处于使用阶段', '照片能分辨脚手架各作业层及层上人员或堆载情况'], 'not_applicable_when': ['脚手架处于搭设或拆除阶段', '照片仅拍到局部单层，无法分辨层数与层上作业状态']}, 'evidence_requirements': ['能覆盖脚手架多个作业层的可见照片', '各层上人员集中作业或材料设备堆载的可见特征', '可区分层数的立杆、横杆或作业层踏板等参照物'], 'disambiguation_notes': ['仅凭单层局部照片不能推断其他层状态，不得据此判 non_compliant', '人员正常通行、少量工具放置不等同于满载作业', '被遮挡层不得直接计入或排除，只有可见证据直接支撑时才判违规'], 'keywords': ['作业脚手架', '满载作业层数', '同时作业层数', '2层', '堆载'], 'similar_words': ['同时施工层数', '同时作业层', '满载层数'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架各作业层及层上人员、材料设备', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-6', 'standard_code': 'GB 51210-2016', 'article': '第11.2.6条', 'align_score': 0.667, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.375, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'LOADED_WORK_LAYERS'},
        {'atomic_rule_id': 'GB51210-2016-11.2.7@fire_prevention', 'clause_text': '在脚手架作业层上进行电焊、气焊和其他动火作业时, 应采取防火措施，并应设专人监护。', 'rule_family': 'visual_direct', 'judge_dimension': '判断脚手架作业层动火作业点是否配置可见的防火措施（接火斗、防火毯、灭火器等），不判断动火审批手续和人员资质。', 'judge_boundary': {'compliant': '作业层动火作业点可见接火斗、防火毯、灭火器等防火措施，且未见违规事实。', 'non_compliant': '作业层上可见正在进行的电焊、气焊或其他动火作业，且作业点及下方未见任何接火斗、防火毯、灭火器等防火措施。', 'doubtful': '动火作业点可见防火措施，但被遮挡或状态无法确认是否有效覆盖火花飞溅区域。'}, 'applicability': {'all_of': ['脚手架作业层上正在进行或刚完成电焊、气焊或其他动火作业'], 'not_applicable_when': ['作业层上未见动火作业迹象', '动火作业不在脚手架作业层上进行']}, 'evidence_requirements': ['可见的动火作业迹象（焊渣、火花、焊机、气瓶等）', '作业点及下方防火措施配置情况'], 'disambiguation_notes': ['防火措施不限于灭火器，接火斗、防火毯、防火隔板均算', '仅看到焊机但未见动火作业，不判违规', '防火措施被遮挡无法确认时，不直接判 non_compliant'], 'keywords': ['脚手架', '作业层', '动火作业', '电焊', '气焊', '防火措施', '接火斗', '灭火器'], 'similar_words': ['焊接作业防火', '动火防火措施', '脚手架动火'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架作业层动火作业点及下方区域', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-7', 'standard_code': 'GB 51210-2016', 'article': '第11.2.7条', 'align_score': 0.5, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.357, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'FIRE_PREVENTION'},
        {'atomic_rule_id': 'GB51210-2016-11.2.7@fire_watch', 'clause_text': '在脚手架作业层上进行电焊、气焊和其他动火作业时, 应采取防火措施，并应设专人监护。', 'rule_family': 'visual_direct', 'judge_dimension': '判断脚手架作业层动火作业时，作业点附近是否可见专职监护人员，不判断监护人员资质和培训记录。', 'judge_boundary': {'compliant': '动火作业点附近可见专职监护人员，且未见违规事实。', 'non_compliant': '作业层上可见正在进行的电焊、气焊或其他动火作业，且作业点附近未见任何监护人员。', 'doubtful': '动火作业点附近有人，但无法判断是否为专职监护人员。'}, 'applicability': {'all_of': ['脚手架作业层上正在进行或刚完成电焊、气焊或其他动火作业'], 'not_applicable_when': ['作业层上未见动火作业迹象', '动火作业不在脚手架作业层上进行']}, 'evidence_requirements': ['可见的动火作业迹象', '作业点附近人员位置和状态'], 'disambiguation_notes': ['监护人员应位于动火点附近且注意力在动火作业上', '仅看到有人经过或作业人员本人，不视为监护人员', '监护人员被遮挡无法确认时，不直接判 non_compliant'], 'keywords': ['脚手架', '作业层', '动火作业', '专人监护', '监护人员'], 'similar_words': ['动火监护', '看火人', '防火监护人'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架作业层动火作业点附近人员', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-11-2-7', 'standard_code': 'GB 51210-2016', 'article': '第11.2.7条', 'align_score': 0.471, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.385, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'FIRE_WATCH'},
        {'atomic_rule_id': 'GB51210-2016-8.2.1@width', 'clause_text': '作业脚手架的宽度不应小于0. 8m,且不宜大于1.2m。 作业层高度不应小于1. 7m,且不宜大于2. Omo', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业脚手架架体宽度（内外立杆之间的净距或作业面宽度）是否满足下限0.8m及上限1.2m的构造要求，不判断连墙件、高度等其他构造。', 'judge_boundary': {'compliant': '在可清晰辨认架体宽度的照片中，实测或目测估算宽度处于0.8m~1.2m之间，且无可见证据表明宽度小于0.8m或大于1.2m。', 'non_compliant': '有可见证据（如卷尺实测、与已知尺寸构件对比）直接显示架体宽度小于0.8m或大于1.2m。', 'doubtful': '同一架体宽度在照片中因透视、遮挡等原因出现互相矛盾的可见特征，无法确定是否在0.8m~1.2m范围内。'}, 'applicability': {'all_of': ['作业脚手架架体已搭设，且照片中可辨认内外立杆或作业面宽度'], 'not_applicable_when': ['非作业脚手架（如支撑脚手架）', '架体宽度被完全遮挡无法辨认', '照片中无任何可参照尺寸的构件']}, 'evidence_requirements': ['能显示架体宽度全貌或局部带参照物的照片', '卷尺实测读数（如有）', '与已知尺寸构件（如钢管直径48mm）的对比'], 'disambiguation_notes': ['宽度指内外立杆之间的净距，不是作业面铺设宽度', '透视变形可能导致目测偏差，需结合参照物', '不宜大于1.2m为推荐性上限，超限时需有设计依据才可判违规'], 'keywords': ['作业脚手架', '架体宽度', '0.8m', '1.2m', '内外立杆间距'], 'similar_words': ['脚手架宽度', '作业面宽度', '架体横向宽度'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架架体宽度', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-2-1', 'standard_code': 'GB 51210-2016', 'article': '第8.2.1条', 'align_score': 0.379, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'WIDTH'},
        {'atomic_rule_id': 'GB51210-2016-8.2.1@height', 'clause_text': '作业脚手架的宽度不应小于0. 8m,且不宜大于1.2m。 作业层高度不应小于1. 7m,且不宜大于2. Omo', 'rule_family': 'visual_direct', 'judge_dimension': '判断作业层高度（作业面至上方横杆或防护栏杆的垂直净高）是否满足下限1.7m及上限2.0m的构造要求，不判断宽度、连墙件等其他构造。', 'judge_boundary': {'compliant': '在可清晰辨认作业层高度的照片中，实测或目测估算高度处于1.7m~2.0m之间，且无可见证据表明高度小于1.7m或大于2.0m。', 'non_compliant': '有可见证据（如卷尺实测、与已知尺寸构件对比）直接显示作业层高度小于1.7m或大于2.0m。', 'doubtful': '同一作业层高度在照片中因透视、遮挡等原因出现互相矛盾的可见特征，无法确定是否在1.7m~2.0m范围内。'}, 'applicability': {'all_of': ['作业脚手架作业层已搭设，且照片中可辨认作业面至上方横杆或防护栏杆的垂直距离'], 'not_applicable_when': ['非作业脚手架', '作业层高度被完全遮挡无法辨认', '照片中无任何可参照尺寸的构件']}, 'evidence_requirements': ['能显示作业层高度全貌或局部带参照物的照片', '卷尺实测读数（如有）', '与已知尺寸构件（如钢管直径48mm）的对比'], 'disambiguation_notes': ['作业层高度指作业面至上方横杆或防护栏杆的垂直净高，不是层高', '不宜大于2.0m为推荐性上限，超限时需有设计依据才可判违规', '需区分作业层高度与步距'], 'keywords': ['作业层高度', '1.7m', '2.0m', '防护栏杆高度', '作业面净高'], 'similar_words': ['作业层净高', '作业面高度', '防护高度'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '作业脚手架作业层高度', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-2-1', 'standard_code': 'GB 51210-2016', 'article': '第8.2.1条', 'align_score': 0.31, 'subject': '架体作业层承脚与承放表面', 'subject_score': 0.5, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'HEIGHT'},
