        {'atomic_rule_id': 'GB51210-2016-8.1.3@matching_components', 'clause_text': '脚手架所用杆件、节点连接件、构配件等应能配套使用， 并应能满足各种组架方法和构造要求。', 'rule_family': 'visual_structural', 'judge_dimension': '判断脚手架杆件、节点连接件、构配件之间是否配套使用，以及是否满足组架方法和构造要求；不判断材料强度、设计计算等不可见内容。', 'judge_boundary': {'compliant': '在可见的杆件、连接件、构配件连接部位，未见规格不匹配、连接不配套或明显无法满足组架构造要求的现象。', 'non_compliant': '可见证据直接显示杆件与连接件规格不匹配（如连接件无法正常扣紧、杆件端头与节点不配套）、构配件混用导致连接失效或明显无法满足组架构造要求。', 'doubtful': '同一可见连接部位存在直接冲突的可见特征（如连接件看似配套但明显松动且无法判断是否因规格不匹配导致），且无法从照片确认。'}, 'applicability': {'all_of': ['脚手架杆件、节点连接件、构配件处于可见状态', '能够观察到连接节点或组架构造'], 'not_applicable_when': ['连接部位被完全遮挡或不可见', '仅涉及材料性能、设计计算等不可见内容']}, 'evidence_requirements': ['清晰显示杆件与连接件连接节点的照片', '能辨认连接件类型、杆件规格及连接状态', '能观察组架构造是否明显异常'], 'disambiguation_notes': ['不要将材料锈蚀、变形等单独判为不配套，除非直接影响配套使用', '不要将设计计算问题纳入本规则判断', '连接件未完全拧紧但规格配套时，不直接判为本条违规'], 'keywords': ['杆件', '节点连接件', '构配件', '配套使用', '组架方法', '构造要求'], 'similar_words': ['配件匹配', '连接件配套', '构配件兼容'], 'scene_hint': 'SCAFFOLD_COUPLER_TYPE', 'subject_hint': '脚手架杆件与节点连接件连接部位', 'subject_cue': '', 'note': '', 'regulation_id': 'STD-GB-51210-2016-8-1-3', 'standard_code': 'GB 51210-2016', 'article': '第8.1.3条', 'align_score': 0.639, 'subject': '施工防护栏杆段与节点', 'subject_score': 0.462, 'subject_origin': 'existing', 'runtime_enabled': True, 'risk_key': 'MATCHING_COMPONENTS'},
