        {'atomic_rule_id': 'GB51210-2016-8.3.11@cantilever_length', 'clause_text': '当支撑脚手架顶层水平杆承受荷载时，应经计算确定其 杆端悬臂长度，并应小于15OmmO', 'rule_family': 'visual_structural', 'judge_dimension': '判断支撑脚手架顶层水平杆杆端悬臂（外伸）长度是否小于150mm；不判断悬臂长度的计算过程与设计文件。', 'judge_boundary': {'compliant': '在可见的顶层水平杆杆端悬臂处，未见悬臂长度达到或超过150mm的可见证据。', 'non_compliant': '可见顶层水平杆杆端悬臂长度明显达到或超过150mm（如与已知尺寸参照物对比明显超限）。', 'doubtful': '同一杆端悬臂的可见长度特征互相矛盾（如不同角度照片显示长度明显不一致），无法判定是否超限。'}, 'applicability': {'all_of': ['场景为支撑脚手架', '顶层水平杆承受荷载', '杆端悬臂长度可见或可借助参照物估算'], 'not_applicable_when': ['非支撑脚手架', '顶层水平杆不承受荷载', '杆端悬臂被完全遮挡无法观察']}, 'evidence_requirements': ['能显示顶层水平杆杆端悬臂全貌的照片', '可辅助估算长度的参照物（如扣件、杆件直径、卷尺等）'], 'disambiguation_notes': ['悬臂长度指水平杆从最近支撑点（如立杆、连接节点）外伸至杆端的距离，不是水平杆总长。', '照片透视可能造成长度误判，需结合参照物或正对拍摄角度判断。', '计算确定悬臂长度属于设计资料，静态照片无法核查，不纳入本规则裁决。'], 'keywords': ['支撑脚手架', '顶层水平杆', '杆端悬臂', '悬臂长度', '150mm'], 'similar_words': ['外伸长度', '悬挑长度', '杆端外露长度'], 'scene_hint': 'SCAFFOLD_CANTILEVER', 'subject_hint': '支撑脚手架顶层水平杆杆端悬臂', 'subject_cue': '顶层水平杆从支撑点向外伸出的一段杆端', 'note': '悬臂长度应经计算确定，计算过程无法从照片核查；本规则仅对可见悬臂长度是否超限作裁决。', 'regulation_id': 'STD-GB-51210-2016-8-3-11', 'standard_code': 'GB 51210-2016', 'article': '第8.3.11条', 'align_score': 0.459, 'subject': '支撑脚手架顶层水平杆杆端悬臂', 'subject_score': 0.308, 'subject_origin': 'new', 'runtime_enabled': True, 'risk_key': 'CANTILEVER_LENGTH'},
